#include <stdio.h>

int main(void) {
  int arr[5] = {10, 20, 30, 40, 50};
  int *p = arr;
  int sum = 0;

  for (int i = 0; i < 5; i++) {
    sum += *(p + i);
    if (i % 2 == 0) {
      *(p + i) = *(p + i) + 1;
    }
  }

  for (int i = 0; i < 5; i++) {
    printf("%d ", arr[i]);
  }
  printf("\n");
  printf("sum=%d\n", sum);

  return 0;
}

def process(lst, idx, acc):
    if idx >= len(lst):
        return acc
    if lst[idx] % 2 == 0:
        acc.append(lst[idx] * 2)
    else:
        acc.append(lst[idx] + 1)
    return process(lst, idx + 1, acc)
numbers = [3, 4, 7, 8, 9]
result = process(numbers, 0, [])
print(result)
total = 0
for n in result:
    total += n
print(total)

